                            return true;
                        case 1:
                            parameter = new EpsgConversionParameterRecord("Longitude of natural origin", -2.135d);
                            return true;
                        case 2:
                            parameter = new EpsgConversionParameterRecord("Scale factor at natural origin", 0.9999999d);
                            return true;
                        case 3:
                            parameter = new EpsgConversionParameterRecord("False easting", 40000.0d);
                            return true;
                        case 4:
                            parameter = new EpsgConversionParameterRecord("False northing", 70000.0d);
                            return true;
                        default:
                            break;
                    }
                    break;
                default:
                    break;
            }

            parameter = default;
            return false;
        }

    }
}
